#!/usr/bin/env bash
set -euo pipefail

helper="${1:-$HOME/bin/git-manage-worktree}"
fixture_dir="$(mktemp -d "${TMPDIR:-/tmp}/worktree-guidance-test.XXXXXX")"
fixture_dir="$(cd "$fixture_dir" && pwd -P)"
trap 'rm -rf "$fixture_dir"' EXIT
repo="$fixture_dir/repo"
mkdir -p "$repo"
git -C "$repo" init -q -b main
export AGENTS_OVERRIDE_TEMPLATE="$fixture_dir/template.md"
export WORKTREES_BASE="$fixture_dir/worktrees"
cat > "$AGENTS_OVERRIDE_TEMPLATE" <<'EOF'
<!-- Generated by ~/bin/git-manage-worktree. Do not edit AGENTS.override.md directly. -->
## Personal implementation workflow
The primary session owns implementation and command execution.
EOF

fail() { echo "FAIL: $*" >&2; exit 1; }
expect_failure() {
  if bash "$helper" "$@" > "$fixture_dir/stdout" 2> "$fixture_dir/stderr"; then
    fail "expected failure: $*"
  fi
  [[ ! -s "$fixture_dir/stdout" ]] || fail "failed guidance printed a success path"
}
write_current() {
  cat > "$repo/AGENTS.md" <<'EOF'
# Kindo Monorepo — Agent Guidance
## Keep guidance current
Preserve this rule.
## Delegation and verification
Plan and review in the main session. Delegate implementation to the cascade `implementer` role and builds, linting, and tests to the cascade `mechanic` role. Use `on-host-qa` for the appropriate format, lint, typecheck, and test workflow. Run `self-review` before a commit.
Additional verification stays here.
## Engineering foundations
Preserve this invariant.
EOF
}

expect_failure guidance "$repo"
grep -q 'no supported delegation section' "$fixture_dir/stderr"
[[ ! -e "$repo/AGENTS.override.md" ]] || fail 'created guidance without a source'

write_current
cp "$repo/.git/info/exclude" "$fixture_dir/exclude.before"
expect_failure guidance --check "$repo"
[[ ! -e "$repo/AGENTS.override.md" ]] || fail 'check created guidance'
cmp "$repo/.git/info/exclude" "$fixture_dir/exclude.before"
bash "$helper" guidance "$repo" > "$fixture_dir/path"
[[ "$(cat "$fixture_dir/path")" == "$repo/AGENTS.override.md" ]] || fail 'wrong output path'
grep -q 'primary session owns' "$repo/AGENTS.override.md"
grep -q 'Preserve this rule' "$repo/AGENTS.override.md"
grep -q 'Preserve this invariant' "$repo/AGENTS.override.md"
grep -q 'Use `on-host-qa`' "$repo/AGENTS.override.md"
grep -q 'Additional verification stays' "$repo/AGENTS.override.md"
if grep -q 'Delegate implementation to the cascade' "$repo/AGENTS.override.md"; then
  fail 'conflicting delegation survived'
fi
git -C "$repo" check-ignore -q AGENTS.override.md
bash "$helper" guidance --check "$repo" > /dev/null
cp "$repo/AGENTS.override.md" "$fixture_dir/first.md"
bash "$helper" guidance "$repo" > /dev/null
cmp "$repo/AGENTS.override.md" "$fixture_dir/first.md"
[[ "$(grep -Fxc '/AGENTS.override.md' "$repo/.git/info/exclude")" == 1 ]] || fail 'duplicate ignore entry'

printf '\nNew canonical rule.\n' >> "$repo/AGENTS.md"
expect_failure guidance --check "$repo"
cmp "$repo/AGENTS.override.md" "$fixture_dir/first.md"
bash "$helper" guidance "$repo" > /dev/null
grep -q 'New canonical rule' "$repo/AGENTS.override.md"
printf '\nNew personal rule.\n' >> "$AGENTS_OVERRIDE_TEMPLATE"
expect_failure guidance --check "$repo"
bash "$helper" guidance "$repo" > /dev/null
grep -q 'New personal rule' "$repo/AGENTS.override.md"

cp "$repo/AGENTS.override.md" "$fixture_dir/good.md"
cat > "$repo/AGENTS.md" <<'EOF'
# Kindo Monorepo
## Delegation and verification
A changed delegation policy that needs explicit handling.
EOF
expect_failure guidance "$repo"
grep -q 'unrecognized delegation instructions' "$fixture_dir/stderr"
cmp "$repo/AGENTS.override.md" "$fixture_dir/good.md"
printf '# Kindo Monorepo\n## Renamed delegation\nNew rules.\n' > "$repo/AGENTS.md"
expect_failure guidance "$repo"
cmp "$repo/AGENTS.override.md" "$fixture_dir/good.md"

cat > "$repo/AGENTS.md" <<'EOF'
# Kindo Monorepo
## Before
Keep before.
## Delegation (cascade)
Delegate old implementation and commands.
### Role details
Old cascade detail.
## After
Keep after.
EOF
bash "$helper" guidance "$repo" > /dev/null
grep -q 'Keep before' "$repo/AGENTS.override.md"
grep -q 'Keep after' "$repo/AGENTS.override.md"
if grep -q 'Old cascade detail\|Delegate old' "$repo/AGENTS.override.md"; then
  fail 'legacy delegation survived'
fi
bash "$helper" guidance --check "$repo" > /dev/null

write_current
git -C "$repo" add AGENTS.md
git -C "$repo" -c core.hooksPath=/dev/null -c commit.gpgSign=false -c user.name=Fixture -c user.email=fixture@example.invalid commit -qm fixture
(cd "$repo" && bash "$helper" add 'test/new-worktree') > "$fixture_dir/added-path" 2> "$fixture_dir/add-log"
new_worktree="$(tail -n 1 "$fixture_dir/added-path")"
[[ "$new_worktree" == "$WORKTREES_BASE/test-new-worktree" ]] || fail 'add output changed'
bash "$helper" guidance --check "$new_worktree" > /dev/null
grep -q 'Preserve this invariant' "$new_worktree/AGENTS.override.md"

echo 'PASS: current and legacy layouts; non-delegation rules retained; missing/stale checks are read-only; source/template refresh; idempotence; unsupported input preserves output; new worktree guidance.'
